import React from "react";
import type { Meta, StoryObj } from "@storybook/react";

import { useTheme } from "aihappey-components";
import type { AihUiTheme, ChatMessage } from "aihappey-types";

type ChatThemeProps = Parameters<AihUiTheme["Chat"]>[0];

type ChatStoryArgs = Omit<ChatThemeProps, "renderMessage" | "renderReactions"> & {
  showReactions?: boolean;
};

const makeTextMessage = (
  partial: Omit<ChatMessage, "content" | "createdAt"> & {
    text: string;
    createdAt?: string;
  }
): ChatMessage => {
  return {
    id: partial.id,
    role: partial.role,
    author: partial.author,
    createdAt: partial.createdAt ?? new Date("2026-01-01T12:00:00.000Z").toISOString(),
    content: [{ type: "text", text: partial.text }],
  };
};

const ChatStory = (args: ChatStoryArgs) => {
  const { Chat } = useTheme() as unknown as Pick<AihUiTheme, "Chat">;
  const { showReactions, ...chatProps } = args;

  return (
    <Chat
      {...chatProps}
      renderMessage={(msg: ChatMessage) => {
        const textPart = msg.content.find((p) => p.type === "text");
        const text = textPart && "text" in textPart ? textPart.text : "(non-text message)";

        return (
          <div style={{ padding: "6px 8px" }}>
            <strong style={{ marginRight: 6 }}>{msg.role.toUpperCase()}:</strong>
            <span>{text}</span>
          </div>
        );
      }}
      renderReactions={
        showReactions
          ? () => <div style={{ padding: "0 8px 8px", opacity: 0.7 }}>👍 2 � 👎 1</div>
          : undefined
      }
    />
  );
};

const meta = {
  title: "Chat",
  component: ChatStory,
  argTypes: {
    messages: { control: false },
    showReactions: { control: { type: "boolean" } },
    locale: { control: { type: "text" } },
